          style={{ padding: '0.8rem 1.5rem', borderRadius: 'var(--radius-md)', fontWeight: 600, display: 'flex', alignItems: 'center', gap: '0.5rem', opacity: flaggedCount === 0 ? 0.5 : 1, cursor: flaggedCount === 0 ? 'not-allowed' : 'pointer' }}
