import { getTotalQuestionCount } from './lib/questionsStore';
import React, { useState, useEffect } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { PrivacyPolicyModal, TermsOfUseModal } from './LegalModals';
import { X, Crown, CheckCircle2, ShieldCheck, Zap, Brain, Loader2 } from 'lucide-react';
import { getOfferings, purchasePackage, restorePurchases } from './lib/revenuecat';

interface Props {
  isOpen: boolean;
  onClose: () => void;
  feature?: string;
}

export function PaywallModal({ isOpen, onClose, feature = "this feature" }: Props) {
  const [packages, setPackages] = useState<any[]>([]);
  const [loading, setLoading] = useState(true);
  const [purchasing, setPurchasing] = useState<string | null>(null);
  const [showPrivacy, setShowPrivacy] = useState(false);
  const [showTerms, setShowTerms] = useState(false);

  async function loadOfferings() {
    setLoading(true);
    const offerings = await getOfferings();
    if (offerings && offerings.current && offerings.current.availablePackages) {
      setPackages(offerings.current.availablePackages);
    }
    setLoading(false);
  };

  useEffect(() => {
    if (isOpen) {
      loadOfferings();
    }
  }, [isOpen]);

  const handlePurchase = async (rcPackage: any) => {
    setPurchasing(rcPackage.identifier);
    const success = await purchasePackage(rcPackage);
    setPurchasing(null);
    if (success) {
      onClose();
      window.location.reload();
    }
  };

  const handleRestore = async () => {
    setLoading(true);
    const success = await restorePurchases();
    setLoading(false);
    if (success) {
      onClose();
      window.location.reload();
    } else {
      alert("No previous purchases found to restore.");
    }
  };

  if (!isOpen) return null;

  return (
    <AnimatePresence>
      <div style={{
        position: 'fixed',
        top: 0, left: 0, right: 0, bottom: 0,
        background: 'rgba(0,0,0,0.6)',
        backdropFilter: 'blur(4px)',
        zIndex: 9999,
        display: 'flex',
        alignItems: 'center',
        justifyContent: 'center',
        padding: '1rem'
      }}>
        <motion.div
          initial={{ opacity: 0, scale: 0.9, y: 20 }}
          animate={{ opacity: 1, scale: 1, y: 0 }}
          exit={{ opacity: 0, scale: 0.9, y: 20 }}
          style={{
            background: 'var(--surface-color)',
            width: '100%',
            maxWidth: '450px',
            borderRadius: '24px',
            overflow: 'hidden',
            boxShadow: '0 25px 50px -12px rgba(0, 0, 0, 0.5)',
            position: 'relative',
            maxHeight: '90vh',
            display: 'flex',
            flexDirection: 'column'
          }}
        >
          <button
            onClick={onClose}
            style={{
              position: 'absolute', top: '1rem', right: '1rem', zIndex: 10,
              background: 'rgba(0,0,0,0.2)', border: 'none', color: '#fff',
              width: '32px', height: '32px', borderRadius: '50%',
              display: 'flex', alignItems: 'center', justifyContent: 'center',
              cursor: 'pointer'
            }}
          >
            <X size={18} />
          </button>

