            </div>

            {loading ? (
              <div style={{ display: 'flex', justifyContent: 'center', padding: '2rem 0' }}>
                <motion.div animate={{ rotate: 360 }} transition={{ repeat: Infinity, duration: 1, ease: 'linear' }}>
                  <Loader2 size={24} color="var(--accent-color)" />
                </motion.div>
              </div>
            ) : packages.length > 0 ? (
    <>
              <div style={{ marginBottom: '0.75rem', padding: '0.5rem', background: 'rgba(234, 179, 8, 0.15)', borderRadius: '8px', border: '1px solid rgba(234, 179, 8, 0.3)', textAlign: 'center' }}>
                <p style={{ margin: 0, fontSize: '0.85rem', color: 'var(--text-primary)', fontWeight: 600 }}>Traditional Canadian prep courses cost $3,000+.<br/><span style={{color: '#eab308'}}>Get the curriculum in your pocket for a fraction of the cost.</span></p>
              </div>
              <div style={{ display: 'flex', flexDirection: 'column', gap: '0.5rem' }}>
                {packages.map((pkg) => (
                  <button
                    key={pkg.identifier}
                    onClick={() => handlePurchase(pkg)}
                    disabled={purchasing !== null}
                    style={{
                      width: '100%',
                      padding: '0.75rem 0.5rem',
                      background: 'var(--accent-color)',
                      color: 'white',
                      border: 'none',
                      borderRadius: '12px',
                      fontSize: '1.05rem',
                      fontWeight: 600,
                      cursor: purchasing !== null ? 'not-allowed' : 'pointer',
                      display: 'flex',
                      alignItems: 'center',
                      justifyContent: 'space-between',
                      transition: 'transform 0.2s, opacity 0.2s',
                      opacity: purchasing !== null && purchasing !== pkg.identifier ? 0.5 : 1,
                      ...(pkg.product.title.toLowerCase().includes('yearly') ? {
                        boxShadow: '0 0 0 2px var(--accent-color), 0 0 15px rgba(59, 130, 246, 0.5)'
                      } : {})
                    }}
                  >
                    <span style={{ display: 'flex', flexDirection: 'column', alignItems: 'flex-start', flex: 1, textAlign: 'left', paddingRight: '0.25rem', minWidth: 0 }}>
                      <span style={{ lineHeight: 1.2, marginBottom: '0.2rem', display: 'flex', alignItems: 'center', gap: '0.25rem', flexWrap: 'wrap' }}>
                        {pkg.product.title.replace(/\\(com\\.ndeb\\.afkprep \\(unreviewed\\)\\)/g, '').trim()}
                        {pkg.product.title.toLowerCase().includes('yearly') && (
                          <span style={{ fontSize: '0.65rem', background: '#fbbf24', color: '#854d0e', padding: '0.15rem 0.4rem', borderRadius: '4px', fontWeight: 800, textTransform: 'uppercase' }}>Best Value</span>
                        )}
                      </span>
                      <span style={{ fontSize: '0.8rem', fontWeight: 400, opacity: 0.9, lineHeight: 1.2 }}>{pkg.product.title.toLowerCase().includes('yearly') ? "Save 30% with an annual plan." : pkg.product.description}</span>
                    </span>
                    <span style={{ display: 'flex', alignItems: 'center', gap: '0.25rem', flexShrink: 0, whiteSpace: 'nowrap', textAlign: 'right' }}>
                      {pkg.product.title.toLowerCase().includes('monthly') ? (
                        <span style={{ display: 'flex', flexDirection: 'column', alignItems: 'flex-end', lineHeight: 1.1 }}>
                          <span style={{ textDecoration: 'line-through', opacity: 0.7, fontSize: '0.65rem', color: '#e2e8f0' }}>$16.99 CAD</span>
                          <span style={{ fontWeight: 800, fontSize: '0.95rem' }}>$9.99 CAD</span>
                        </span>
                      ) : pkg.product.title.toLowerCase().includes('annual') ? (
                        <span style={{ display: 'flex', flexDirection: 'column', alignItems: 'flex-end', lineHeight: 1.1 }}>
                          <span style={{ textDecoration: 'line-through', opacity: 0.7, fontSize: '0.65rem', color: '#e2e8f0' }}>$203.88 CAD</span>
                          <span style={{ fontWeight: 800, fontSize: '0.95rem' }}>$142.99 CAD</span>
                        </span>
                      ) : (
                        <span>{pkg.product.priceString}</span>
                      )}
                      {purchasing === pkg.identifier ? <motion.div animate={{ rotate: 360 }} transition={{ repeat: Infinity, duration: 1, ease: 'linear' }}><Loader2 size={16} /></motion.div> : <Crown size={16} />}
                    </span>
                  </button>
                ))}
              </div>
            </>
            ) : (
              <div style={{ textAlign: 'center', padding: '1rem', background: 'var(--surface-hover)', borderRadius: '12px' }}>
                <p style={{ margin: 0, fontSize: '0.9rem', color: 'var(--text-secondary)' }}>
                  Pricing packages are currently unavailable.
                </p>
              </div>
            )}

            <div style={{ marginTop: '0.75rem', textAlign: 'center' }}>
               <button 
                 onClick={handleRestore}
                 disabled={loading || purchasing !== null}
                 style={{ 
                   background: 'none', border: 'none', color: 'var(--text-secondary)',
                   fontSize: '0.85rem', cursor: 'pointer', textDecoration: 'underline'
                 }}
               >
                 Restore Purchases
               </button>
            </div>

            <div style={{ marginTop: '1rem', textAlign: 'center', fontSize: '0.65rem', color: 'var(--text-secondary)', opacity: 0.8, lineHeight: 1.3 }}>
               Payment will be charged to your Apple/Google account at confirmation of purchase. Subscription automatically renews unless canceled at least 24 hours before the end of the current period. Account will be charged for renewal within 24-hours prior to the end of the current period. You can manage and cancel your subscriptions in your account settings.
               <div style={{ marginTop: '0.5rem', display: 'flex', justifyContent: 'center', gap: '1rem' }}>
                 <button onClick={() => setShowTerms(true)} style={{ background: 'none', border: 'none', color: 'var(--accent-color)', fontSize: '0.7rem', cursor: 'pointer', textDecoration: 'underline', padding: 0 }}>Terms of Use</button>
                 <button onClick={() => setShowPrivacy(true)} style={{ background: 'none', border: 'none', color: 'var(--accent-color)', fontSize: '0.7rem', cursor: 'pointer', textDecoration: 'underline', padding: 0 }}>Privacy Policy</button>
               </div>
            </div>
            
            <PrivacyPolicyModal isOpen={showPrivacy} onClose={() => setShowPrivacy(false)} />
            <TermsOfUseModal isOpen={showTerms} onClose={() => setShowTerms(false)} />

          </div>
        </motion.div>
      </div>
    </AnimatePresence>
  );
}

import { getTotalQuestionCount } from './lib/questionsStore';
import React, { useState, useEffect, useRef } from 'react';

import { getQuestions, loadTopicQuestions, loadAllQuestions } from './lib/questionsStore';
import { TextToSpeech } from '@capacitor-community/text-to-speech';
import { Capacitor } from '@capacitor/core';

import { topics } from './lib/data';

import { ArrowLeft } from 'lucide-react';

import { PaywallModal } from './PaywallModal';

import { getTopicProgress, usePremiumStatus, saveProgress, getFlaggedQuestions, toggleFlagQuestion, logSRSAnswer, getDueSRSQuestions, logQuizAttempt, getActiveMockExam, saveActiveMockExam, clearActiveMockExam, getMistakes, logMistake, removeMistake, awardBadge, getGamification } from './lib/storage';



// Sub-components

import { QuizHeader } from './quiz/QuizHeader';

import { QuestionCard } from './quiz/QuestionCard';

import { ResultBottomSheet } from './quiz/ResultBottomSheet';


interface Props {

  topicId: string;

  onFinish: (score: number, total: number, breakdown?: Record<string, { correct: number; total: number }>) => void;

  onBack: () => void;

}



export function Quiz({ topicId, onFinish, onBack }: Props) {
  // --- Badge Awarding Logic ---
  const checkAndAwardBadges = (totalAnswered: number, totalCorrect: number) => {
    const accuracy = totalAnswered > 0 ? (totalCorrect / totalAnswered) * 100 : 0;

    if (totalAnswered >= 1) awardBadge('first-step');
    if (totalAnswered >= 10) awardBadge('warm-up-10');
    if (totalAnswered >= 50) awardBadge('on-a-roll-50');
    if (totalAnswered >= 100) awardBadge('century-club-100');
    if (totalAnswered >= 250) awardBadge('quarter-millennium-250');
    if (totalAnswered >= 500) awardBadge('halfway-500');
    if (totalAnswered >= 1000) awardBadge('question-master-1000');
    if (totalAnswered >= 5000) awardBadge('elite-scholar-5000');

    if (totalAnswered >= 20 && accuracy >= 70) awardBadge('sharp-mind-70');
    if (totalAnswered >= 50 && accuracy >= 80) awardBadge('high-achiever-80');
    if (totalAnswered >= 100 && accuracy >= 90) awardBadge('diamond-standard-90');

    const gamif = getGamification();
    if (gamif.currentStreak >= 3) awardBadge('streak-3');
    if (gamif.currentStreak >= 7) awardBadge('streak-7');
    if (gamif.currentStreak >= 30) awardBadge('streak-30');
  };



  // Modes

  const isFlaggedMode = topicId === 'flagged';

  const isSimulatedMode = topicId === 'simulated';

  const isSRSMode = topicId === 'srs_review';

  const isMistakesMode = topicId === 'mistakes';

  

  const breakdownRef = useRef<Record<string, { correct: number; total: number }>>({});

  const sessionStartRef = useRef({ index: 0, score: 0 });



  const [topicQuestions, setTopicQuestions] = useState<any[]>([]);
  const [totalAvailable, setTotalAvailable] = useState(0);

  const [topicName, setTopicName] = useState("");

  const [currentIndex, setCurrentIndex] = useState(0);

  const [score, setScore] = useState(0);

  const [selectedAnswer, setSelectedAnswer] = useState<number | null>(null);

  const handleFinish = () => {
    if (!isSimulatedMode && !isMistakesMode && !isSRSMode) {
        saveProgress(topicId, score, topicQuestions.length, 0, true, topicQuestions.length);
    }
    if (isSimulatedMode) {
      clearActiveMockExam();
    }
    recordSessionAttempt(score, currentIndex + (selectedAnswer !== null ? 1 : 0));
    onFinish(score, topicQuestions.length, breakdownRef.current);
  };
  const question = topicQuestions[currentIndex];

  const [isFlagged, setIsFlagged] = useState(false);

  const [initialized, setInitialized] = useState(false);

  const [isPlayingAudio, setIsPlayingAudio] = useState(false);
  const cancelAudioRef = useRef(false);

  
  const stopSpeech = async () => {
    cancelAudioRef.current = true;
    try {
      if (Capacitor.isNativePlatform()) {
        await TextToSpeech.stop();
      } else {
        if (window.speechSynthesis) window.speechSynthesis.cancel();
      }
    } catch (e) { /* ignore */ }
  };
const [timeLeft, setTimeLeft] = useState(7200); // 2.0 hours

  const [isShuffled, setIsShuffled] = useState(false);

  const [showPaywall, setShowPaywall] = useState(false);
  

  const isPremium = usePremiumStatus();



  const recordSessionAttempt = (finalScore: number, finalIndex: number) => {

    if (isFlaggedMode || isMistakesMode || isSRSMode || isSimulatedMode) return;

    const sessionAnswered = finalIndex - sessionStartRef.current.index;

    const sessionScore = finalScore - sessionStartRef.current.score;

    if (sessionAnswered > 0) {

      logQuizAttempt(topicId, sessionScore, sessionAnswered);

    }

    sessionStartRef.current = { index: finalIndex, score: finalScore };

  };



  // Initialize questions

  useEffect(() => {

    const init = async () => {

      let qList = [];

      const currentPremium = isPremium;



      if (isSimulatedMode) {

        const activeMock = getActiveMockExam();

        const isExpired = activeMock?.endTime ? (activeMock.endTime - Date.now()) <= 0 : false;

        const isCompleted = activeMock ? activeMock.currentIndex >= activeMock.questions.length : false;



        if (activeMock && activeMock.questions.length > 0 && !isExpired && !isCompleted) {

          qList = activeMock.questions;

          setCurrentIndex(activeMock.currentIndex);

          setScore(activeMock.score);

          sessionStartRef.current = { index: activeMock.currentIndex, score: activeMock.score };

          if (activeMock.endTime) {

            const remaining = Math.floor((activeMock.endTime - Date.now()) / 1000);

            setTimeLeft(Math.max(0, remaining));

          }

        } else {

          await loadAllQuestions();

          let fullList = [...getQuestions()];
          if (!isPremium) {
            const premiumIds = topics.filter(t => t.isPremiumOnly).map(t => t.id);
            fullList = fullList.filter(q => !premiumIds.includes(q.topicId));
          }
          qList = fullList.sort(() => Math.random() - 0.5).slice(0, 100);

          const endTime = Date.now() + 7200 * 1000;

          setTimeLeft(7200);

          saveActiveMockExam({ questions: qList, currentIndex: 0, score: 0, endTime });

        }

        setTopicName("Simulated AFK Exam");

      } else if (isFlaggedMode || isMistakesMode || isSRSMode) {
        await loadAllQuestions();
        const allQs = getQuestions();
        if (isFlaggedMode) {
          const flags = getFlaggedQuestions();
          qList = allQs.filter((q: any) => flags.includes(q.topicId + '-' + q.id));
          setTopicName("Flagged Review");
        } else if (isMistakesMode) {
          const mistakes = getMistakes();
          qList = allQs.filter((q: any) => mistakes.includes(q.topicId + '-' + q.id));
          setTopicName("Weakness Drilling");
        } else if (isSRSMode) {
          const dueIds = getDueSRSQuestions();
          qList = allQs.filter((q: any) => dueIds.includes(q.topicId + '-' + q.id));
          setTopicName("Daily SRS Review");
        }
      } else {
          qList = await loadTopicQuestions(topicId);
          setTopicName(topics.find(t => t.id === topicId)?.name || "");
        }
        
        if (!isSimulatedMode) {
          setTotalAvailable(qList.length);
          if (!currentPremium) qList = qList.slice(0, 100);
        }
        
        if (!isSimulatedMode && !isMistakesMode && !isSRSMode) {
          const progress = getTopicProgress(topicId);
          if (progress && !progress.isFinished) {
            let loadedIndex = progress.currentIndex;
            if (loadedIndex >= qList.length) loadedIndex = Math.max(0, qList.length - 1);
            setCurrentIndex(loadedIndex);
            setScore(progress.currentScore);
            sessionStartRef.current = { index: loadedIndex, score: progress.currentScore };
          }
        }

      setTopicQuestions(qList);

      setInitialized(true);

    };

    init();

  }, [topicId, isSimulatedMode, isFlaggedMode, isSRSMode]);



  // Update flagged status when current question changes

  useEffect(() => {

    if (topicQuestions.length > 0 && initialized) {

      const currentQuestion = topicQuestions[currentIndex];

      if (currentQuestion && currentQuestion.id) {

        const currentFlags = getFlaggedQuestions();

        const compositeId = currentQuestion.topicId + '-' + currentQuestion.id;

        setIsFlagged(currentFlags.includes(compositeId));

      }

    }

  }, [currentIndex, topicQuestions, initialized]);



  // Timer for simulated mode

  useEffect(() => {

    if (!isSimulatedMode || !initialized || topicQuestions.length === 0) return;

    if (timeLeft <= 0) {

      handleFinish();

      return;

    }

    const timerId = setInterval(() => setTimeLeft(t => t - 1), 1000);

    return () => clearInterval(timerId);

  }, [isSimulatedMode, initialized, timeLeft]);



  // Clean up audio on unmount

  useEffect(() => {

    return () => { stopSpeech(); };

  }, []);



  const handleSelect = (index: number) => {

    if (!question || selectedAnswer !== null) return;

    setSelectedAnswer(index);

    const isAnsCorrect = index === question.correctAnswer;

    let newScore = score;

    if (isAnsCorrect) {

      newScore = score + 1;

      setScore(newScore);

    }

    

    if (!isAnsCorrect) {

      logMistake(question.topicId + '-' + question.id);

    } else if (isMistakesMode) {

      removeMistake(question.topicId + '-' + question.id);

    }



    if (isSimulatedMode) {

      const breakdown = breakdownRef.current;

      if (!breakdown[question.topicId]) {

        breakdown[question.topicId] = { correct: 0, total: 0 };

      }

      breakdown[question.topicId].total += 1;

      if (isAnsCorrect) breakdown[question.topicId].correct += 1;

    }

    

    if (!isSimulatedMode && !isFlaggedMode && !isMistakesMode) logSRSAnswer(question.topicId + '-' + question.id, isAnsCorrect);



    if (!isSimulatedMode && !isMistakesMode && !isSRSMode) {
        saveProgress(topicId, newScore, topicQuestions.length, currentIndex, false, currentIndex + 1);
      checkAndAwardBadges(currentIndex + 1, newScore);

    }



    if (isSimulatedMode) {

      const activeMock = getActiveMockExam();

      saveActiveMockExam({ questions: topicQuestions, currentIndex, score: newScore, endTime: activeMock?.endTime });

    }

  };



  
  const handlePrev = () => {
    if (currentIndex > 0) {
      setCurrentIndex(c => c - 1);
      setSelectedAnswer(null);
    }
  };

  const handleNext = () => {

    if (currentIndex < topicQuestions.length - 1) {

      const nextIdx = currentIndex + 1;

      setCurrentIndex(nextIdx);

      setSelectedAnswer(null);

      stopSpeech();

      setIsPlayingAudio(false);



      if (!isSimulatedMode && !isMistakesMode && !isSRSMode) {
        saveProgress(topicId, score, topicQuestions.length, nextIdx, false, currentIndex + 1);

      }

      if (isSimulatedMode) {

        const activeMock = getActiveMockExam();

        saveActiveMockExam({ questions: topicQuestions, currentIndex: nextIdx, score, endTime: activeMock?.endTime });

      }

    } else {

      handleFinish();

    }

  };



  



  const handleToggleFlag = () => {

    if (!question) return;

    const flagged = toggleFlagQuestion(question.topicId + '-' + question.id);

    setIsFlagged(flagged);

  };



  const handleToggleShuffle = () => {

    if (!isShuffled) {

      setTopicQuestions(prev => {

        const done = prev.slice(0, currentIndex);

        const remaining = [...prev.slice(currentIndex)].sort(() => Math.random() - 0.5);

        return [...done, ...remaining];

      });

    } else {

      if (!isSimulatedMode) {
          // Reset to original order
          if (isFlaggedMode || isMistakesMode || isSRSMode) {
            const allQs = getQuestions();
            let qList = [];
            if (isFlaggedMode) {
              const flags = getFlaggedQuestions();
              qList = allQs.filter(q => flags.includes(q.topicId + '-' + q.id));
            } else if (isMistakesMode) {
              const mistakes = getMistakes();
              qList = allQs.filter(q => mistakes.includes(q.topicId + '-' + q.id));
            } else if (isSRSMode) {
              const dueIds = getDueSRSQuestions();
              qList = allQs.filter(q => dueIds.includes(q.topicId + '-' + q.id));
            }
            setTopicQuestions(qList);
          } else {
            loadTopicQuestions(topicId).then(qList => {
              if (!isPremium) qList = qList.slice(0, 100);
              setTopicQuestions(qList);
            });
          }

      }

    }

    setIsShuffled(prev => !prev);

    setSelectedAnswer(null);

  };



  const handleRestartMockExam = () => {

    clearActiveMockExam();

    let fullList = [...getQuestions()];
    if (!isPremium) {
      const premiumIds = topics.filter(t => t.isPremiumOnly).map(t => t.id);
      fullList = fullList.filter(q => !premiumIds.includes(q.topicId));
    }
    const qList = fullList.sort(() => Math.random() - 0.5).slice(0, 100);

    const endTime = Date.now() + 7200 * 1000;

    setTimeLeft(7200);

    saveActiveMockExam({ questions: qList, currentIndex: 0, score: 0, endTime });

    

    breakdownRef.current = {};

    setTopicQuestions(qList);

    setCurrentIndex(0);

    setScore(0);

    setSelectedAnswer(null);

  };



  const playAudio = async (elementId: string, fallbackText: string) => {
    if (isPlayingAudio) { 
      stopSpeech(); 
      setIsPlayingAudio(false); 
      return; 
    }
    
    cancelAudioRef.current = false;
    setIsPlayingAudio(true);
    
    const el = document.getElementById(elementId);
    let textToRead = el?.innerText || fallbackText;
    
    // Cleanup the text slightly for better TTS parsing
    textToRead = textToRead.replace(/([A-D])\s/g, "$1. "); 
    
    // Chunk the text into sentences to bypass Android's 5-10 second engine delay
    // This feeds the engine small chunks so it starts speaking instantly
    const chunks = (textToRead.match(/[^.!?\n]+[.!?\n]+/g) || [textToRead]).map(c => c.trim()).filter(c => c.length > 0);
    
    const isFrench = document.cookie.includes('googtrans=/en/fr');
    const lang = isFrench ? 'fr-FR' : 'en-US';

    if (Capacitor.isNativePlatform()) {
      try {
        for (let i = 0; i < chunks.length; i++) {
          if (cancelAudioRef.current) break;
          await TextToSpeech.speak({
            text: chunks[i],
            lang: lang,
            rate: 1.0,
            pitch: 1.0,
            category: 'playback'
          });
        }
      } catch (e) {
        console.error("TTS Native Error", e);
      }
      setIsPlayingAudio(false);
    } else {
      if (!window.speechSynthesis) {
        setIsPlayingAudio(false);
        return;
      }
      
      const playChunk = (index: number) => {
        if (cancelAudioRef.current || index >= chunks.length) {
          setIsPlayingAudio(false);
          return;
        }
        
        const utterance = new SpeechSynthesisUtterance(chunks[index]);
        utterance.lang = lang;
        utterance.onend = () => playChunk(index + 1);
        utterance.onerror = () => setIsPlayingAudio(false);
        window.speechSynthesis.speak(utterance);
      };
      
      playChunk(0);
    }
  };



  const handleBackClick = () => {

    stopSpeech();

    recordSessionAttempt(score, currentIndex + (selectedAnswer !== null ? 1 : 0));

    onBack();

  };



  // Auto-record progress on unmount if any questions were answered

  const lastRecordedRef = useRef({ score: 0, index: 0 });

  const stateRef = useRef({ score, currentIndex, selectedAnswer, topicId });



  useEffect(() => {

    stateRef.current = { score, currentIndex, selectedAnswer, topicId };

  }, [score, currentIndex, selectedAnswer, topicId]);



  useEffect(() => {

    return () => {

      const { score: finalScore, currentIndex: finalIdx, selectedAnswer: selAns, topicId: tid } = stateRef.current;

      const finalIndex = finalIdx + (selAns !== null ? 1 : 0);



      // Prevent double recording if we already recorded this exact state (e.g. via Finish button)

      if (finalIndex > sessionStartRef.current.index && (finalIndex !== lastRecordedRef.current.index || finalScore !== lastRecordedRef.current.score)) {

        const sessionAnswered = finalIndex - sessionStartRef.current.index;

        const sessionScore = finalScore - sessionStartRef.current.score;

        if (sessionAnswered > 0) {

          logQuizAttempt(tid, sessionScore, sessionAnswered);

          lastRecordedRef.current = { score: finalScore, index: finalIndex };

        }

      }

    };

  }, []); // Run ONLY on actual unmount



  // Keyboard and Swipe

  useEffect(() => {

    const handleKeyDown = (e: KeyboardEvent) => {

      if ((e.target as HTMLElement)?.tagName === 'INPUT') return;

      if (selectedAnswer === null) {

        if (['1', 'a', 'A'].includes(e.key)) handleSelect(0);

        else if (['2', 'b', 'B'].includes(e.key)) handleSelect(1);

        else if (['3', 'c', 'C'].includes(e.key)) handleSelect(2);

        else if (['4', 'd', 'D'].includes(e.key)) handleSelect(3);

      } else {

        if (e.key === 'Enter' || e.key === ' ') { e.preventDefault(); handleNext(); }

      }

      if (e.key === 'f' || e.key === 'F') handleToggleFlag();

    };

    window.addEventListener('keydown', handleKeyDown);

    return () => window.removeEventListener('keydown', handleKeyDown);

  }, [selectedAnswer, currentIndex, topicQuestions]);



  useEffect(() => {

    let startX = 0, startY = 0;

    const onStart = (e: TouchEvent) => { startX = e.touches[0].clientX; startY = e.touches[0].clientY; };

    const onEnd = (e: TouchEvent) => {

      const dx = e.changedTouches[0].clientX - startX;

      const dy = e.changedTouches[0].clientY - startY;

      if (Math.abs(dx) > 60 && Math.abs(dx) > Math.abs(dy) * 1.5) {

        if (dx < 0 && selectedAnswer !== null) handleNext();

        else if (dx > 0) { if (currentIndex === 0) handleBackClick(); else handlePrev(); }

      }

    };

    document.addEventListener('touchstart', onStart, { passive: true });

    document.addEventListener('touchend', onEnd, { passive: true });

    return () => { document.removeEventListener('touchstart', onStart); document.removeEventListener('touchend', onEnd); };

  }, [selectedAnswer, currentIndex]);



  if (!initialized || topicQuestions.length === 0) {

    return initialized ? (

      <div style={{ padding: '2rem', textAlign: 'center', marginTop: '4rem' }}>

        <h2>{isFlaggedMode ? "No flagged questions." : isSRSMode ? "No questions due for review." : "No questions available."}</h2>

        <button onClick={onBack} className="primary-btn" style={{ marginTop: '2rem' }}>Go Back</button>

      </div>

    ) : null;

  }

  



  const progressPercentage = (currentIndex + (selectedAnswer !== null ? 1 : 0)) / topicQuestions.length * 100;



  return (

    <div style={{ padding: 'clamp(0.5rem, 3vw, 1rem)', paddingBottom: selectedAnswer !== null ? '65vh' : '12vh', maxWidth: '800px', margin: '0 auto', width: '100%' }}>

      <button 

        onClick={handleBackClick}

        style={{ display: 'flex', alignItems: 'center', gap: '0.5rem', color: 'var(--text-secondary)', marginBottom: '1.5rem', background: 'none', border: 'none', cursor: 'pointer', padding: 0 }}

      >

        <ArrowLeft size={20} /> Back

      </button>



      {!isPremium && !isSimulatedMode && totalAvailable > 100 && (

        <div 

          onClick={() => setShowPaywall(true)}

          className="paywall-banner"

          style={{ background: 'linear-gradient(135deg, rgba(245, 158, 11, 0.1) 0%, rgba(217, 119, 6, 0.1) 100%)', border: '1px solid rgba(245, 158, 11, 0.3)', padding: '0.8rem 1rem', borderRadius: 'var(--radius-md)', display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '1.5rem', cursor: 'pointer', flexWrap: 'wrap', gap: '0.5rem' }}

        >

          <div style={{ display: 'flex', alignItems: 'center', gap: '0.5rem', color: '#d97706', fontSize: '0.9rem', fontWeight: 600 }}>

            <span translate="no">Free Tier Preview: Viewing {topicQuestions.length}/{totalAvailable} questions.</span>

          </div>

          <button 
            onClick={(e) => { e.stopPropagation(); setShowPaywall(true); }}
            style={{
              background: 'linear-gradient(135deg, #f59e0b 0%, #d97706 100%)',
              color: 'white',
              border: 'none',
              padding: '0.4rem 1rem',
              borderRadius: '20px',
              fontWeight: 700,
              fontSize: '0.85rem',
              cursor: 'pointer',
              boxShadow: '0 2px 8px rgba(217, 119, 6, 0.3)',
              textTransform: 'uppercase',
              letterSpacing: '0.05em'
            }}
          >
            Unlock All
          </button>

        </div>

      )}



      <QuizHeader

        topicName={topicName}

        isSimulatedMode={isSimulatedMode}

        isSRSMode={isSRSMode}

        isFlaggedMode={isFlaggedMode}

        timeLeft={timeLeft}

        isShuffled={isShuffled}

        onToggleShuffle={handleToggleShuffle}

        onRestartMockExam={handleRestartMockExam}

        isFlagged={isFlagged}

        onToggleFlag={handleToggleFlag}
        currentIndex={currentIndex}

        totalQuestions={topicQuestions.length}

        progressPercentage={progressPercentage}

        formatTime={(s) => {

          const h = Math.floor(s / 3600), m = Math.floor((s % 3600) / 60), sec = s % 60;

          return h > 0 ? `${h}:${m.toString().padStart(2, '0')}:${sec.toString().padStart(2, '0')}` : `${m.toString().padStart(2, '0')}:${sec.toString().padStart(2, '0')}`;

        }}

      />



      <QuestionCard

        question={question}

        currentIndex={currentIndex}

        selectedAnswer={selectedAnswer}

        isAnswered={selectedAnswer !== null}

        onSelect={handleSelect}

        isPlayingAudio={isPlayingAudio}

        onToggleAudio={playAudio}

      />



      <ResultBottomSheet

        isAnswered={selectedAnswer !== null}

        isCorrect={selectedAnswer === question.correctAnswer}

        isSimulatedMode={isSimulatedMode}

        explanation={question.explanation}

        correctAnswerText={question.options[question.correctAnswer]}

        isPlayingAudio={isPlayingAudio}

        onToggleAudio={playAudio}

        onNext={handleNext}
        onPrev={handlePrev}
        currentIndex={currentIndex}        isLastQuestion={currentIndex === topicQuestions.length - 1}
      />
      
      <div style={{ textAlign: 'center', marginTop: '2rem', marginBottom: '1rem', padding: '1rem', opacity: 0.7 }}>
        <p style={{ margin: 0, fontSize: '0.85rem', color: 'var(--text-secondary)' }}>
          Found a mistake? Email our dental review board at <br/>
          <a href={`mailto:ndebpreppro@gmail.com?subject=Question Error Report ID: ${question?.id}`} style={{ color: 'var(--accent-color)', fontWeight: 600, textDecoration: 'none' }}>ndebpreppro@gmail.com</a>
        </p>
      </div>



      <PaywallModal isOpen={showPaywall} onClose={() => setShowPaywall(false)} feature={`all ${getTotalQuestionCount().toLocaleString()} questions`} />
      

    </div>

  );

}

